html:
{% block content %}

<style>
    @media print {
        @page {
            size: A4;
            margin: 25mm 15mm 20mm 15mm;
        }

        .page-break {
            page-break-before: always;
        }
    }

    body {
        font-family: Arial, sans-serif;
        font-size: 13px;
        margin: 0;
        padding: 0;
    }

    .page {
        position: relative;
        padding: 100px 20px 80px 20px; /* Header/Footer space */
        min-height: 1000px;
    }

    .page img.header,
    .page img.footer {
        width: 100%;
        height: auto;
        pointer-events: none;
    }

    .header-container {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        text-align: center;
        pointer-events: none;
    }

    .footer-container {
        position: absolute;
        bottom: 0;
        left: 0;
        width: 100%;
        height: 122px;
        text-align: center;
        pointer-events: none;
    }

    .main-content {
        padding-top: 13px;
        padding-bottom: 10px;
    }

    .section-title {
        text-align: center;
        font-weight: bold;
        font-size: 14px;
        text-transform: uppercase;
        margin-bottom: 7px;
    }

    .details-table {
        width: 100%;
        border-collapse: collapse;
        margin-top: 12px;
    }

    .details-table th,
    .details-table td {
        border: 1px solid #000;
        padding: 5px 5px;
        text-align: left;
        vertical-align: top;
        font-size: 12.5px;
        width:25%;
    }

    .remarks-box {
        margin-top: 16px;
    }

    .remarks-box label {
        font-weight: bold;
    }

    .remarks-box textarea {
        width: 100%;
        height: 70px;
        padding: 7px;
        font-size: 13px;
        border: 1px solid #000;
        resize: none;
    }

    .bold-text {
        font-weight: bold;
        font-size: 12px;
        margin-top: 16px;
    }
</style>

{% for row in doc.reinsurers %}
<div class="page{% if not loop.first %} page-break{% endif %}">

    <!-- Per-page Header -->
    <div class="header-container">
        <img src="/files/Header.jpg" alt="Header Image" class="header">
    </div>

    <!-- Content Area -->
    <div class="main-content">
        <div class="section-title">FACULTATIVE REINSURANCE</div>
        <div class="section-title">REINSURANCE BORDEREAU</div>

        <table class="details-table">
            <tr><th>REINSURER</th><td>{{row.resolved_name}}<br>{{row.address}}</td></tr>
            <tr><th>ORIGINAL INSURED</th><td>{{doc.resolved_name}}</td></tr>
            <tr><th>CLASS OF BUSINESS</th><td>{{row.riskdescription}}</td></tr>
            <tr><th>REFERENCE</th><td>{{doc.document_ref}}</td></tr>
            <tr><th>OUR POLICY NO</th><td>{{doc.insurance_ref}}</td></tr>
            <tr><th>POLICY PERIOD</th><td>From: {{frappe.format_date(doc.cover_start_date)}} To: {{frappe.format_date(doc.expiry_date)}}</td></tr>
            <tr><th>SUM INSURED</th><td>As per schedule</td></tr>
            <tr><th>TOTAL PREMIUM <strong>{{frappe.format(row.premium_percent, {'fieldtype': 'Float'})}}%</strong></th><td>P {{frappe.format(row.total_premium, {'fieldtype': 'Float'})}}</td></tr>
            <tr><th>TOTAL COMMISSION <strong>{{frappe.format(row.commission_percent, {'fieldtype': 'Float'})}}%</strong></th><td>P {{frappe.format(row.total_commission, {'fieldtype': 'Float'})}}</td></tr>
            <tr><th>NET DUE TO YOU</th><td>{{frappe.format(row.net_due, {'fieldtype': 'Currency'})}}</td></tr>
            
        </table>

        <div class="remarks-box">
            <label for="remarks">REMARKS:</label>
            <textarea id="remarks" name="remarks" placeholder="Write your remarks here..."></textarea>
        </div>

        <p class="bold-text">Please contact us immediately if you have any queries relating to this reinsurance.</p>
        <p><strong>Prepared By: </strong>{{doc.created_by}} <strong>Reviewed By: </strong>{{frappe.get_fullname()}}</p>
        <p><strong>Authorised: </strong>_____________  <strong>Date: </strong>{{frappe.format_date(frappe.utils.today())}}</p>
    </div>

    <!-- Per-page Footer -->
    <div class="footer-container">
        <img src="/files/Footer.jpg" alt="Footer Image" class="footer">
    </div>
</div>
{% endfor %}

{% endblock %}
